package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import java.util.*;import org.w3c.dom.*;
/** Synthetic pending confirmations; actual Activity destruction is mandatory. */
final class ManagerConfirmationChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;final Set<String> chosen=new HashSet<>(Arrays.asList("1","2"));
 ManagerConfirmationChecks(MapAndroidChecks m){this.m=m;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);}
 String positive(String k){return k.equals("delete")?"Удалить":k.equals("show")?"Показать":k.equals("hide")?"Скрыть":"Вставить";}
 boolean paste(String k){return k.startsWith("paste");}
 long insert(Object store,String k)throws Exception{String xml=ManagerRotationChecks.XML;if(k.equals("show"))xml=xml.replace("<name>QA_ROTATE_POINT</name>","<name>QA_ROTATE_POINT</name><visibility>0</visibility>");Object doc=r.parse(xml.getBytes("UTF-8"));for(String id:new String[]{"point","other","nested"})m.staticCall("MediaLinks","add",new Class[]{m.codec,Element.class,String.class,String.class,byte[].class},doc,m.element(doc,id),id+".jpg","image/jpeg",new byte[]{2,5,8});return (Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_CONFIRM_"+k);}
 void open(long id,String k)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("QA_ROTATE_POINT");m.click("QA_ROTATE_OTHER");if(paste(k)){m.managerAction(k.equals("pastecut")?"Вырезать":"Копировать");m.geometryReady();m.openManagerFolder("QA_ROTATE_FOLDER");m.managerAction("Вставить в эту папку");m.geometryReady();}else{m.setListingForm("QA_ROTATE_POINT",0,0,0,false,false,0);m.managerAction(k.equals("delete")?"Удалить выбранное":k.equals("show")?"Показать выбранные":"Скрыть выбранные");}m.waitText(positive(k));m.waitForIdleSync();}
 Map<String,?> prefs(){return new HashMap<>(m.getTargetContext().getSharedPreferences("object-manager-view",0).getAll());}
 String clip(Object store)throws Exception{Object c=m.objectClip(store);return c==null?"":m.clipStamp(c);}
 Object field(Object o,String n)throws Exception{return o.getClass().getField(n).get(o);}
 void identity(long id,String k,String token,String stamp,String message)throws Exception{Object d=m.managerField("confirmationDraft");m.check(d!=null,"pending confirmation exists");m.check((Long)field(d,"project")==id&&k.equals(field(d,"action"))&&token.equals(field(d,"token")),"original project/action/token retained");m.check((paste(k)?"0":"").equals(field(d,"destination"))&&(paste(k)?"Корень проекта / QA_ROTATE_FOLDER":"").equals(field(d,"destinationLabel"))&&(paste(k)?stamp:"").equals(field(d,"fingerprint")),"original target and buffer identity retained");m.check(Arrays.equals((int[])d.getClass().getMethod("indices").invoke(d),new int[]{2,3}),"original source indices retained");m.check(message.equals(field(d,"message")),"original preview not rebased");}
 boolean enabled(String k){final boolean[] e={false};m.runOnMainSync(()->{View b=v.button(m.activeDialogRoot(),positive(k));e[0]=b!=null&&b.isEnabled();});return e[0];}
 void rotate(int direction,long id,String k,String token,String stamp,String message,boolean enabled)throws Exception{Activity old=m.activity;v.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"actual Activity destruction: "+k);m.waitText(positive(k));m.waitForIdleSync();identity(id,k,token,stamp,message);m.check(enabled(k)==enabled,"confirmation enabled only for original XML/buffer");v.controlReachable(positive(k));v.controlReachable("Отмена");}
 void replace(Object store,long id,String k,String token,String old)throws Exception{m.staticCall("ObjectClipboardWrites","capture",new Class[]{m.storeClass,long.class,boolean.class,List.class,String.class},store,id,k.equals("pastecut"),Arrays.asList("1","2"),token);m.check(!old.equals(clip(store)),"identical-content recapture has different generation");}
 void unchanged(Object store,long id,byte[] xml,Map<String,byte[]> assets,String stamp,Map<String,?> settings)throws Exception{m.check(Arrays.equals(xml,r.xml(r.load(store,id))),"cancel/reject/recreation keeps exact KML");r.sameAssets(r.load(store,id),assets);m.check(stamp.equals(clip(store)),"cancel/reject/recreation retains current buffer");m.check(settings.equals(prefs()),"cancel/reject/recreation retains applied settings");}
 void stripDeclarations(Element e){NamedNodeMap a=e.getAttributes();List<String> remove=new ArrayList<>();for(int i=0;i<a.getLength();i++)if("http://www.w3.org/2000/xmlns/".equals(a.item(i).getNamespaceURI()))remove.add(a.item(i).getNodeName());for(String n:remove)e.removeAttribute(n);for(Node n=e.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element)stripDeclarations((Element)n);}
 String elementToken(Element node)throws Exception{Element holder=node.getOwnerDocument().createElementNS("http://www.opengis.net/kml/2.2","Document");holder.appendChild(node);return (String)m.staticCall("ObjectTree","token",new Class[]{Element.class},holder);}
 void confirmed(Object store,long id,String k,Object before,String token,String oldClip,Map<String,byte[]> assets)throws Exception{m.click(positive(k));m.geometryReady();m.waitText("Изменения сохранены");Object actual=r.load(store,id);Element root=(Element)m.call(actual,"root",new Class[]{});if(k.equals("pastecopy")){NodeList nodes=m.element(actual,"folder").getElementsByTagNameNS("*","Placemark");List<Element> added=new ArrayList<>();for(int i=0;i<nodes.getLength();i++){Element n=(Element)nodes.item(i);if(!n.getAttribute("id").equals("nested"))added.add(n);}m.check(added.size()==2,"copy creates exactly two target subtrees");Set<String> names=new HashSet<>();for(Element c:added){String name=c.getElementsByTagNameNS("*","name").item(0).getTextContent();names.add(name);Element source=m.element(before,name.equals("QA_ROTATE_POINT")?"point":"other"),copy=(Element)c.cloneNode(true),original=(Element)source.cloneNode(true);m.check(!c.getAttribute("id").equals(source.getAttribute("id")),"copy gets fresh id");copy.setAttribute("id",source.getAttribute("id"));stripDeclarations(copy);stripDeclarations(original);m.check(elementToken(copy).equals(elementToken(original)),"clone preserves geometry/altitude/style/date/media except new id");}m.check(names.equals(new HashSet<>(Arrays.asList("QA_ROTATE_POINT","QA_ROTATE_OTHER"))),"copy uses original sources");Object clean=r.parse(r.xml(actual));Element target=m.element(clean,"folder");List<Node> remove=new ArrayList<>();for(Node n=target.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element&&"Placemark".equals(n.getLocalName())&&!((Element)n).getAttribute("id").equals("nested"))remove.add(n);for(Node n:remove)target.removeChild(n);m.check(m.treeToken(clean).equals(token),"all original XML remains unchanged after copy");m.uniqueIds(root,new HashSet<String>());Object c=m.objectClip(store);m.check(c!=null&&!(Boolean)field(c,"cut")&&(Long)field(c,"project")==id&&m.treeToken(actual).equals(field(c,"token"))&&new HashSet<>((List<String>)field(c,"keys")).equals(chosen),"copy buffer retains originals and new XML token");m.check(!oldClip.equals(clip(store)),"successful copy advances buffer identity");}
  else{Object expected=r.parse(r.xml(before));Element er=(Element)m.call(expected,"root",new Class[]{});if(k.equals("pastecut"))m.staticCall("ObjectTree","move",new Class[]{Element.class,Collection.class,String.class,String.class},er,new ArrayList<>(chosen),"0",token);else if(k.equals("delete"))m.staticCall("ObjectTree","delete",new Class[]{Element.class,Collection.class,String.class},er,new ArrayList<>(chosen),token);else m.staticCall("ObjectVisibility","apply",new Class[]{Element.class,Collection.class,boolean.class,String.class},er,new ArrayList<>(chosen),k.equals("show"),token);m.check(m.treeToken(expected).equals(m.treeToken(actual)),"explicit action changes only intended XML");m.check(k.equals("pastecut")?m.objectClip(store)==null:oldClip.equals(clip(store)),"cut consumed once; other actions retain buffer");}r.sameAssets(actual,assets);m.check(m.managerField("confirmationDraft")==null,"success dismisses pending confirmation");}
 void scenario(Object store,String k,String outcome)throws Exception{long id=insert(store,k);try{open(id,k);Object before=r.load(store,id);byte[] xml=r.xml(before);String token=m.treeToken(before),stamp=clip(store),message=(String)field(m.managerField("confirmationDraft"),"message");Map<String,byte[]> assets=new HashMap<>(m.assets(before));Map<String,?> settings=prefs();identity(id,k,token,stamp,message);m.check(enabled(k),"initial confirmation requires explicit action");boolean staleBefore=outcome.equals("stale-before"),replaceBefore=outcome.equals("replace-before"),clearBefore=outcome.equals("clear-before");if(staleBefore)r.externalChange(store,id,true);if(replaceBefore)replace(store,id,k,token,stamp);if(clearBefore)m.staticCall("ObjectClipboardWrites","clear",new Class[]{m.storeClass},store);byte[] current=r.xml(r.load(store,id));String currentStamp=clip(store);rotate(UiAutomation.ROTATION_FREEZE_90,id,k,token,stamp,message,!staleBefore&&!replaceBefore&&!clearBefore);if(outcome.equals("cancel")||staleBefore||replaceBefore||paste(k)&&outcome.equals("confirm"))v.snapshot("confirm-"+k+"-"+outcome,false);m.check(Arrays.equals(current,r.xml(r.load(store,id)))&&currentStamp.equals(clip(store)),"recreation never applies or consumes buffer");if(!staleBefore)m.check(settings.equals(prefs()),"unchanged XML recreation retains all settings");
  if(outcome.equals("confirm"))confirmed(store,id,k,before,token,stamp,assets);
  else if(outcome.equals("cancel")){rotate(UiAutomation.ROTATION_FREEZE_0,id,k,token,stamp,message,true);v.snapshot("confirm-"+k+"-return",false);m.click("Отмена");unchanged(store,id,xml,assets,stamp,settings);}
  else if(staleBefore||replaceBefore||clearBefore){m.waitText("Действие заблокировано");if(staleBefore)m.check(m.managerKeys("selected").isEmpty(),"shifted XML clears obsolete selected indices");Map<String,?> now=prefs();m.click("Отмена");unchanged(store,id,current,assets,currentStamp,now);}
  else{if(outcome.equals("replace-after"))replace(store,id,k,token,stamp);else if(outcome.equals("clear-after"))m.staticCall("ObjectClipboardWrites","clear",new Class[]{m.storeClass},store);else r.externalChange(store,id,false);byte[] newer=r.xml(r.load(store,id));String newerStamp=clip(store);Map<String,?> now=prefs();m.click(positive(k));m.geometryReady();m.waitText(outcome.equals("replace-after")?"Буфер изменился":outcome.equals("clear-after")?"Буфер объектов пуст":"Проект изменился");if(!outcome.equals("clear-after"))v.snapshot("confirm-"+k+"-rejected-"+outcome,false);m.click("Понятно");identity(id,k,token,stamp,message);unchanged(store,id,newer,assets,newerStamp,now);rotate(UiAutomation.ROTATION_FREEZE_0,id,k,token,stamp,message,false);Map<String,?> afterRotation=prefs();m.click("Отмена");unchanged(store,id,newer,assets,newerStamp,afterRotation);}
  m.check(m.managerField("confirmationDraft")==null,"Cancel/success removes confirmation");Activity old=m.activity;v.rotate(m.activity.getResources().getConfiguration().orientation==1?UiAutomation.ROTATION_FREEZE_90:UiAutomation.ROTATION_FREEZE_0);m.check(old!=m.activity&&old.isDestroyed(),"dismissed main really recreated");m.check(m.managerField("confirmationDraft")==null,"dismissed confirmation never reopens");v.emit("CONFIRM_RESULT kind="+k+" outcome="+outcome+" PASS");
 }finally{v.finish();m.staticCall("ObjectClipboardWrites","clear",new Class[]{m.storeClass},store);m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store,String k)throws Exception{long source=insert(store,k),other=-1;try{Object doc=r.load(store,source);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_CONFIRM_FOREIGN");m.check(m.treeToken(doc).equals(m.treeToken(r.load(store,other))),"other project has identical XML");v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(other);m.waitText("QA_ROTATE_OTHER");open(source,k);String stamp=clip(store);Map<String,?> settings=prefs();final long target=other;m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",target)));Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"foreign confirmation really recreated");v.snapshot("confirm-"+k+"-foreign",false);v.emit("CONFIRM_FOREIGN_VIEW kind="+k+" expected="+other+" actual="+m.managerField("project")+" folder="+m.managerField("folder"));m.check((Long)m.managerField("project")==other&&m.managerField("confirmationDraft")==null&&m.managerKeys("selected").isEmpty()&&"".equals(m.managerField("folder")),"other project keeps its own root view and rejects old confirmation/sources");m.waitText("QA_ROTATE_OTHER");m.check(settings.equals(prefs()),"foreign confirmation never changes either project's stored settings");m.check(Arrays.equals(xml,r.xml(r.load(store,source)))&&Arrays.equals(xml,r.xml(r.load(store,other)))&&stamp.equals(clip(store)),"foreign guard retains both documents and clipboard");r.sameAssets(r.load(store,source),assets);r.sameAssets(r.load(store,other),assets);v.emit("CONFIRM_FOREIGN kind="+k+" PASS");}finally{v.finish();m.staticCall("ObjectClipboardWrites","clear",new Class[]{m.storeClass},store);m.call(store,"remove",new Class[]{long.class},source);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void hierarchy(Object store)throws Exception{long id=insert(store,"show");try{Object doc=r.load(store,id);Element root=(Element)m.call(doc,"root",new Class[]{});m.staticCall("ObjectVisibility","apply",new Class[]{Element.class,Collection.class,boolean.class,String.class},root,Arrays.asList("0","0/0"),false,m.treeToken(doc));m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,doc);doc=r.load(store,id);String token=m.treeToken(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("QA_ROTATE_FOLDER");m.openManagerFolder("QA_ROTATE_FOLDER");m.click("QA_ROTATE_NESTED");m.managerAction("Показать выбранные");m.waitText("собственная видимость: 2");Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"ancestor/child confirmation really recreated");v.snapshot("confirm-hierarchy",false);m.click("Показать");m.geometryReady();m.waitText("Изменения сохранены");Object expected=r.parse(r.xml(doc));m.staticCall("ObjectVisibility","apply",new Class[]{Element.class,Collection.class,boolean.class,String.class},m.call(expected,"root",new Class[]{}),Arrays.asList("0","0/0"),true,token);m.check(m.treeToken(expected).equals(m.treeToken(r.load(store,id))),"ancestor and explicitly selected child keep separate own flags");r.sameAssets(r.load(store,id),assets);v.emit("CONFIRM_HIERARCHY PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run(boolean pasteGroup)throws Exception{m.installTileFixture();int network=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());try{String[] kinds=pasteGroup?new String[]{"pastecopy","pastecut"}:new String[]{"delete","show","hide"};for(String k:kinds){for(String outcome:new String[]{"cancel","confirm","stale-before","stale-after"})scenario(store,k,outcome);if(pasteGroup)for(String outcome:new String[]{"replace-before","replace-after","clear-before","clear-after"})scenario(store,k,outcome);}for(String k:kinds)foreign(store,k);if(!pasteGroup)hierarchy(store);m.check(m.requests.get()==network,"confirmations issue no tile requests");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
